"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def SlidingWindowMaximum(arr, k):
    result = []
    deque = []
    # Stores indices
    for i in range(0, len(arr)):
        if ((not (len(deque) == 0)) and (deque[0] <= (i - k))):
            deque.pop(0)
        while ((not (len(deque) == 0)) and (arr[deque[-1]] <= arr[i])):
            deque.pop(-1)
        deque.append(i)
        if (i >= (k - 1)):
            result.append(arr[deque[0]])
    return result
print(SlidingWindowMaximum([1, 3, -1, -3, 5, 3, 6, 7], 3))